input.command:
python3 << 'EOF'
import json

with open('/root/package-lock.json', 'r') as f:
    lock_data = json.load(f)

# Get installed versions
installed_versions = {}

# Check in dependencies
if 'dependencies' in lock_data:
    for pkg_name, pkg_info in lock_data['dependencies'].items():
        if isinstance(pkg_info, dict):
            version = pkg_info.get('version')
            if version:
                installed_versions[pkg_name] = version

# Check in packages (npm 7+)
if 'packages' in lock_data:
    for pkg_path, pkg_info in lock_data['packages'].items():
        if isinstance(pkg_info, dict):
            version = pkg_info.get('version')
            if version:
                # Extract package name from path
                if pkg_path.startswith('node_modules/'):
                    pkg_name = pkg_path[len('node_modules/'):]
                else:
                    pkg_name = pkg_path
                installed_versions[pkg_name] = version

# Print some examples
print("Sample installed versions:")
for pkg in ['@babel/traverse', '@xmldom/xmldom', 'braces', 'cross-spawn', 'form-data', 'ip', 'json5', 'marked', 'qs', 'semver', 'tar', 'tar-fs', 'ws', 'yaml']:
    version = installed_versions.get(pkg, 'NOT FOUND')
    print(f"  {pkg}: {version}")

# Save to file for next script
with open('/tmp/installed_versions.json', 'w') as f:
    json.dump(installed_versions, f)

print(f"\nTotal packages with versions: {len(installed_versions)}")

EOF
